package org.jsoup.helper;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class Validate_ESTest_test30 extends Validate_ESTest_scaffolding {

    /**
     * Validate.notNull should reject a null argument by throwing an
     * IllegalArgumentException (the ValidationException it raises is a subclass).
     */
    @Test(timeout = 4000)
    public void notNullRejectsNullObject() throws Throwable {
        try {
            Validate.notNull((Object) null);
            fail("Expecting exception: IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Expected: "Object must not be null", thrown from Validate.notNull
            verifyException("org.jsoup.helper.Validate", e);
        }
    }
}
